local config_osgi = "osgi"

mapper("uci_1to1").registerConfigMap(config_osgi)

local osgi_config = {
  config = config_osgi,
  section = "config",
  type = "osgi",
  options = {
    "enabled",
    "storage_dir",
    "num_logfile",
    "logfilesize",
    "logdir",
    "loglevel",
    "memory_limit",
    "log_enable",
    "cert_enable",
    "restart_count_after_oom",
    "enable_syslog",
    "enable_watchdog_on_bundles",
    "backoff_minwait",
    "backoff_multiplier"
  },
}

mapper("uci_1to1").registerSimpleMap(osgi_config)

local osgi_bundle_url = {
  config = config_osgi,
  type = "bundle_url",
  options = {
    "url",
  }
}

mapper("uci_1to1").registerNamedMultiMap(osgi_bundle_url)
